namespace ghidra.app.util.exporter;





using ghidra.app.util;
using ghidra.app.util;
using ghidra.framework.model;
using ghidra.framework.model;
using ghidra.program.database;
using ghidra.program.model.address;
using ghidra.util;
using ghidra.util.exception;
using ghidra.util.task;

public class GzfExporter : Exporter {

	public static readonly string EXTENSION = "gzf";
	public static readonly string SUFFIX = "." + EXTENSION;

	public static readonly string NAME = "Ghidra Zip File";

	public GzfExporter() : base(NAME, EXTENSION, new HelpLocation("ExporterPlugin", "gzf"))
    {
	}

	/* @Override */
	public bool canExportDomainFile(DomainFile domainFile) {
		// Avoid exporting link-file itself or non-Program files
		return !domainFile.isLink() && canExportDomainObject(domainFile.getDomainObjectClass());
	}

	/* @Override */
	public bool canExportDomainObject(Class<DomainObject> domainObjectClass) {
		return typeof(ProgramDB).isAssignableFrom(domainObjectClass);
	}

	/* @Override */
	public bool equals(object obj) {
		return (obj is GzfExporter);
	}

	/* @Override */
	public bool export(File file, DomainObject domainObj, AddressSetView addrSet,
			TaskMonitor monitor) {
		if (!canExportDomainObject(domainObj.GetType())) {
			throw new UnsupportedOperationException("only ProgramDB objects are supported");
		}
		try {
			file.delete();
			domainObj.saveToPackedFile(file, monitor);
		}
		catch (UnsupportedOperationException e) {
			log.appendMsg("Content does not support packed file export!");
			log.appendException(e);
			return false;
		}
		catch (CancelledException ce) {
			return false;
		}
		catch (Exception e) {
			log.appendMsg("Unexpected exception exporting file: " + e.getMessage());
			return false;
		}
		return true;
	}

	/* @Override */
	public bool export(File file, DomainFile domainFile, TaskMonitor monitor)
    {
		if (!canExportDomainFile(domainFile)) {
			throw new UnsupportedOperationException("only ProgramDB files are supported");
		}
		try {
			domainFile.packFile(file, monitor);
		}
		catch (CancelledException e) {
			return false;
		}
		catch (Exception e) {
			log.appendMsg("Unexpected exception exporting file: " + e.getMessage());
			return false;
		}
		return true;
	}

	/* @Override */
	public List<Option> getOptions(DomainObjectService domainObjectService) {
		return EMPTY_OPTIONS;
	}

	/* @Override */
	public void setOptions(List<Option> options) {
		// no options for this exporter
	}

	/**
	 * Returns false.  GZF export only supports entire database.
	 */
	/* @Override */
	public bool supportsAddressRestrictedExport() {
		return false;
	}
}
